#!/bin/bash
set -euo pipefail

cd /home/cva6

if [[ -f /etc/cva6_tools_path.sh ]]; then
  source /etc/cva6_tools_path.sh
fi
export PATH="/tools/verilator/bin:${PATH}"
unset VERILATOR_ROOT
unset VERILATOR_BIN

TB_DIR=/home/cva6/.tb_cache_ctrl_axi_align
OBJ_DIR="${TB_DIR}/obj_dir"
BUILD_LOG="${TB_DIR}/build.log"
RUN_LOG="${TB_DIR}/run.log"
TB_TOP=tb_cache_ctrl_axi_align

rm -rf "${TB_DIR}"
mkdir -p "${TB_DIR}"

cat > "${TB_DIR}/${TB_TOP}.sv" <<'EOF'
module tb_cache_ctrl_axi_align;
  timeunit 1ns;
  timeprecision 1ps;

  import config_pkg::*;
  import ariane_pkg::*;
  import std_cache_pkg::*;

  localparam config_pkg::cva6_cfg_t CVA6Cfg = build_config_pkg::build_config(cva6_config_pkg::cva6_cfg);

  localparam type cache_line_t = struct packed {
    logic [CVA6Cfg.DCACHE_TAG_WIDTH-1:0]  tag;
    logic [CVA6Cfg.DCACHE_LINE_WIDTH-1:0] data;
    logic                                 valid;
    logic                                 dirty;
  };

  localparam type cl_be_t = struct packed {
    logic [(CVA6Cfg.DCACHE_TAG_WIDTH+7)/8-1:0]   tag;
    logic [(CVA6Cfg.DCACHE_LINE_WIDTH+7)/8-1:0]  data;
    logic [CVA6Cfg.DCACHE_SET_ASSOC-1:0]         vldrty;
  };

  localparam type dcache_req_i_t = struct packed {
    logic [CVA6Cfg.DCACHE_INDEX_WIDTH-1:0]  address_index;
    logic [CVA6Cfg.DCACHE_TAG_WIDTH-1:0]    address_tag;
    logic [CVA6Cfg.XLEN-1:0]                data_wdata;
    logic [CVA6Cfg.DCACHE_USER_WIDTH-1:0]   data_wuser;
    logic                                   data_req;
    logic                                   data_we;
    logic [(CVA6Cfg.XLEN/8)-1:0]            data_be;
    logic [1:0]                             data_size;
    logic [CVA6Cfg.DcacheIdWidth-1:0]       data_id;
    logic                                   kill_req;
    logic                                   tag_valid;
  };

  localparam type dcache_req_o_t = struct packed {
    logic                                   data_gnt;
    logic                                   data_rvalid;
    logic [CVA6Cfg.DcacheIdWidth-1:0]       data_rid;
    logic [CVA6Cfg.XLEN-1:0]                data_rdata;
    logic [CVA6Cfg.DCACHE_USER_WIDTH-1:0]   data_ruser;
  };

  localparam logic [CVA6Cfg.DCACHE_INDEX_WIDTH-1:0] TargetIndex = 12'h004;
  localparam logic [CVA6Cfg.DCACHE_TAG_WIDTH-1:0]   TargetTag = '0;
  localparam logic [CVA6Cfg.XLEN-1:0]               TargetWdata = 32'hA5A5_1122;
  localparam logic [(CVA6Cfg.XLEN/8)-1:0]           TargetBe = '1;
  localparam logic [7:0]                            ExpectedBe = 8'hF0;
  localparam logic [63:0]                           ExpectedWdata = {TargetWdata, 32'h0000_0000};

  logic clk_i;
  logic rst_ni;
  logic flush_i;
  logic bypass_i;
  logic busy_o;
  dcache_req_i_t req_port_i;
  dcache_req_o_t req_port_o;
  logic [CVA6Cfg.DCACHE_SET_ASSOC-1:0] req_o;
  logic [CVA6Cfg.DCACHE_INDEX_WIDTH-1:0] addr_o;
  logic gnt_i;
  cache_line_t data_o;
  cl_be_t be_o;
  logic [CVA6Cfg.DCACHE_TAG_WIDTH-1:0] tag_o;
  cache_line_t [CVA6Cfg.DCACHE_SET_ASSOC-1:0] data_i;
  logic we_o;
  logic [CVA6Cfg.DCACHE_SET_ASSOC-1:0] hit_way_i;
  miss_req_t miss_req_o;
  logic miss_gnt_i;
  logic active_serving_i;
  logic [63:0] critical_word_i;
  logic critical_word_valid_i;
  logic bypass_gnt_i;
  logic bypass_valid_i;
  logic [63:0] bypass_data_i;
  logic [55:0] mshr_addr_o;
  logic mshr_addr_matches_i;
  logic mshr_index_matches_i;

  cache_ctrl #(
    .CVA6Cfg(CVA6Cfg),
    .cache_line_t(cache_line_t),
    .cl_be_t(cl_be_t),
    .dcache_req_i_t(dcache_req_i_t),
    .dcache_req_o_t(dcache_req_o_t)
  ) dut (
    .clk_i(clk_i),
    .rst_ni(rst_ni),
    .flush_i(flush_i),
    .bypass_i(bypass_i),
    .busy_o(busy_o),
    .req_port_i(req_port_i),
    .req_port_o(req_port_o),
    .req_o(req_o),
    .addr_o(addr_o),
    .gnt_i(gnt_i),
    .data_o(data_o),
    .be_o(be_o),
    .tag_o(tag_o),
    .data_i(data_i),
    .we_o(we_o),
    .hit_way_i(hit_way_i),
    .miss_req_o(miss_req_o),
    .miss_gnt_i(miss_gnt_i),
    .active_serving_i(active_serving_i),
    .critical_word_i(critical_word_i),
    .critical_word_valid_i(critical_word_valid_i),
    .bypass_gnt_i(bypass_gnt_i),
    .bypass_valid_i(bypass_valid_i),
    .bypass_data_i(bypass_data_i),
    .mshr_addr_o(mshr_addr_o),
    .mshr_addr_matches_i(mshr_addr_matches_i),
    .mshr_index_matches_i(mshr_index_matches_i)
  );

  always #5 clk_i = ~clk_i;

  task automatic fail_test(input string msg);
    $display("FAIL: %s", msg);
    $fatal(1, "%s", msg);
  endtask

  initial begin
    clk_i = 1'b0;
    rst_ni = 1'b0;
    flush_i = 1'b0;
    bypass_i = 1'b0;
    req_port_i = '0;
    gnt_i = 1'b1;
    data_i = '{default: '0};
    hit_way_i = '0;
    miss_gnt_i = 1'b0;
    active_serving_i = 1'b0;
    critical_word_i = '0;
    critical_word_valid_i = 1'b0;
    bypass_gnt_i = 1'b0;
    bypass_valid_i = 1'b0;
    bypass_data_i = '0;
    mshr_addr_matches_i = 1'b0;
    mshr_index_matches_i = 1'b0;

    repeat (2) @(posedge clk_i);
    rst_ni = 1'b1;

    @(negedge clk_i);
    req_port_i.address_index = TargetIndex;
    req_port_i.address_tag = TargetTag;
    req_port_i.data_wdata = TargetWdata;
    req_port_i.data_req = 1'b1;
    req_port_i.data_we = 1'b1;
    req_port_i.data_be = TargetBe;
    req_port_i.data_size = 2'b10;
    req_port_i.data_id = '0;
    req_port_i.kill_req = 1'b0;
    req_port_i.tag_valid = 1'b0;

    @(posedge clk_i);
    @(posedge clk_i);
    #1;

    if (!miss_req_o.valid) begin
      fail_test("miss_req_o.valid was not asserted");
    end
    if (!miss_req_o.bypass) begin
      fail_test("uncacheable store did not route through bypass path");
    end
    if (miss_req_o.be !== ExpectedBe) begin
      fail_test($sformatf("byte enable mismatch: expected 0x%02h got 0x%02h", ExpectedBe, miss_req_o.be));
    end
    if (miss_req_o.wdata !== ExpectedWdata) begin
      fail_test($sformatf("write data mismatch: expected 0x%016h got 0x%016h", ExpectedWdata, miss_req_o.wdata));
    end

    $display("PASS: miss_req_o.be=0x%02h miss_req_o.wdata=0x%016h", miss_req_o.be, miss_req_o.wdata);
    $finish;
  end
endmodule
EOF

cat > "${TB_DIR}/cva6_config_pkg.sv" <<'EOF'
package cva6_config_pkg;

  localparam CVA6ConfigXlen = 32;

  localparam CVA6ConfigRVF = 0;
  localparam CVA6ConfigF16En = 0;
  localparam CVA6ConfigF16AltEn = 0;
  localparam CVA6ConfigF8En = 0;
  localparam CVA6ConfigFVecEn = 0;

  localparam CVA6ConfigCvxifEn = 0;
  localparam CVA6ConfigCExtEn = 1;
  localparam CVA6ConfigZcbExtEn = 0;
  localparam CVA6ConfigZcmpExtEn = 0;
  localparam CVA6ConfigAExtEn = 1;
  localparam CVA6ConfigHExtEn = 0;
  localparam CVA6ConfigBExtEn = 0;
  localparam CVA6ConfigVExtEn = 0;
  localparam CVA6ConfigRVZiCond = 0;

  localparam CVA6ConfigAxiIdWidth = 4;
  localparam CVA6ConfigAxiAddrWidth = 64;
  localparam CVA6ConfigAxiDataWidth = 64;
  localparam CVA6ConfigFetchUserEn = 0;
  localparam CVA6ConfigFetchUserWidth = CVA6ConfigXlen;
  localparam CVA6ConfigDataUserEn = 0;
  localparam CVA6ConfigDataUserWidth = CVA6ConfigXlen;

  localparam CVA6ConfigIcacheByteSize = 16384;
  localparam CVA6ConfigIcacheSetAssoc = 4;
  localparam CVA6ConfigIcacheLineWidth = 128;
  localparam CVA6ConfigDcacheByteSize = 32768;
  localparam CVA6ConfigDcacheSetAssoc = 8;
  localparam CVA6ConfigDcacheLineWidth = 128;

  localparam CVA6ConfigDcacheIdWidth = 1;
  localparam CVA6ConfigMemTidWidth = 2;

  localparam CVA6ConfigWtDcacheWbufDepth = 8;

  localparam CVA6ConfigSuperscalarEn = 0;
  localparam CVA6ConfigNrCommitPorts = 2;
  localparam CVA6ConfigNrScoreboardEntries = 8;

  localparam CVA6ConfigFpgaEn = 0;

  localparam CVA6ConfigNrLoadPipeRegs = 1;
  localparam CVA6ConfigNrStorePipeRegs = 0;
  localparam CVA6ConfigNrLoadBufEntries = 2;

  localparam CVA6ConfigInstrTlbEntries = 2;
  localparam CVA6ConfigDataTlbEntries = 2;
  localparam CVA6ConfigUseSharedTlb = 0;
  localparam CVA6ConfigSharedTlbDepth = 0;

  localparam CVA6ConfigRASDepth = 2;
  localparam CVA6ConfigBTBEntries = 32;
  localparam CVA6ConfigBHTEntries = 128;

  localparam CVA6ConfigTvalEn = 1;

  localparam CVA6ConfigNrPMPEntries = 8;

  localparam CVA6ConfigPerfCounterEn = 1;

  localparam config_pkg::cache_type_t CVA6ConfigDcacheType = config_pkg::WB;

  localparam CVA6ConfigMmuPresent = 1;

  localparam CVA6ConfigRvfiTrace = 1;

  localparam MemBytes = CVA6ConfigDcacheByteSize / CVA6ConfigDcacheSetAssoc * 4 * 32;
  localparam MemWords = MemBytes >> ($clog2(CVA6ConfigXlen / 8));

  localparam CachedAddrBeg = MemBytes >> ($clog2(CVA6ConfigXlen / 8));

  localparam config_pkg::cva6_user_cfg_t cva6_cfg = '{
      XLEN: unsigned'(CVA6ConfigXlen),
      FpgaEn: bit'(CVA6ConfigFpgaEn),
      NrCommitPorts: unsigned'(CVA6ConfigNrCommitPorts),
      AxiAddrWidth: unsigned'(CVA6ConfigAxiAddrWidth),
      AxiDataWidth: unsigned'(CVA6ConfigAxiDataWidth),
      AxiIdWidth: unsigned'(CVA6ConfigAxiIdWidth),
      AxiUserWidth: unsigned'(CVA6ConfigDataUserWidth),
      MemTidWidth: unsigned'(CVA6ConfigMemTidWidth),
      NrLoadBufEntries: unsigned'(CVA6ConfigNrLoadBufEntries),
      RVF: bit'(CVA6ConfigRVF),
      RVD: bit'(CVA6ConfigRVF),
      XF16: bit'(CVA6ConfigF16En),
      XF16ALT: bit'(CVA6ConfigF16AltEn),
      XF8: bit'(CVA6ConfigF8En),
      RVA: bit'(CVA6ConfigAExtEn),
      RVB: bit'(CVA6ConfigBExtEn),
      RVV: bit'(CVA6ConfigVExtEn),
      RVC: bit'(CVA6ConfigCExtEn),
      RVH: bit'(CVA6ConfigHExtEn),
      RVZCB: bit'(CVA6ConfigZcbExtEn),
      RVZCMP: bit'(CVA6ConfigZcmpExtEn),
      XFVec: bit'(CVA6ConfigFVecEn),
      CvxifEn: bit'(CVA6ConfigCvxifEn),
      RVZiCond: bit'(CVA6ConfigRVZiCond),
      NrScoreboardEntries: unsigned'(CVA6ConfigNrScoreboardEntries),
      PerfCounterEn: bit'(CVA6ConfigPerfCounterEn),
      MmuPresent: bit'(CVA6ConfigMmuPresent),
      RVS: bit'(1),
      RVU: bit'(1),
      HaltAddress: 64'h800,
      ExceptionAddress: 64'h808,
      RASDepth: unsigned'(CVA6ConfigRASDepth),
      BTBEntries: unsigned'(CVA6ConfigBTBEntries),
      BHTEntries: unsigned'(CVA6ConfigBHTEntries),
      DmBaseAddress: 64'h0,
      TvalEn: bit'(CVA6ConfigTvalEn),
      NrPMPEntries: unsigned'(CVA6ConfigNrPMPEntries),
      PMPCfgRstVal: {16{64'h0}},
      PMPAddrRstVal: {16{64'h0}},
      PMPEntryReadOnly: 16'd0,
      NOCType: config_pkg::NOC_TYPE_AXI4_ATOP,
      NrNonIdempotentRules: unsigned'(2),
      NonIdempotentAddrBase: 1024'({64'b0, 64'b0}),
      NonIdempotentLength: 1024'({64'b0, 64'b0}),
      NrExecuteRegionRules: unsigned'(3),
      ExecuteRegionAddrBase: 1024'({64'h8000_0000, 64'h1_0000, 64'h0}),
      ExecuteRegionLength: 1024'({64'h40000000, 64'h10000, 64'h1000}),
      NrCachedRegionRules: unsigned'(1),
      CachedRegionAddrBase: 1024'(CachedAddrBeg),
      CachedRegionLength: 1024'({64'h40000000}),
      MaxOutstandingStores: unsigned'(7),
      DebugEn: bit'(1),
      AxiBurstWriteEn: bit'(0),
      IcacheByteSize: unsigned'(CVA6ConfigIcacheByteSize),
      IcacheSetAssoc: unsigned'(CVA6ConfigIcacheSetAssoc),
      IcacheLineWidth: unsigned'(CVA6ConfigIcacheLineWidth),
      DCacheType: CVA6ConfigDcacheType,
      DcacheByteSize: unsigned'(CVA6ConfigDcacheByteSize),
      DcacheSetAssoc: unsigned'(CVA6ConfigDcacheSetAssoc),
      DcacheLineWidth: unsigned'(CVA6ConfigDcacheLineWidth),
      DataUserEn: unsigned'(CVA6ConfigDataUserEn),
      WtDcacheWbufDepth: int'(CVA6ConfigWtDcacheWbufDepth),
      FetchUserWidth: unsigned'(CVA6ConfigFetchUserWidth),
      FetchUserEn: unsigned'(CVA6ConfigFetchUserEn),
      InstrTlbEntries: int'(CVA6ConfigInstrTlbEntries),
      DataTlbEntries: int'(CVA6ConfigDataTlbEntries),
      UseSharedTlb: bit'(CVA6ConfigUseSharedTlb),
