      NrLoadPipeRegs: int'(CVA6ConfigNrLoadPipeRegs),
      NrStorePipeRegs: int'(CVA6ConfigNrStorePipeRegs),
      DcacheIdWidth: int'(CVA6ConfigDcacheIdWidth)
  };

endpackage
EOF

set +e
verilator -sv --timing --binary --build \
  --top-module "${TB_TOP}" \
  --Mdir "${OBJ_DIR}" \
  -Wno-fatal -Wno-WIDTH -Wno-UNUSEDSIGNAL -Wno-CASEINCOMPLETE -Wno-TIMESCALEMOD \
  -I/home/cva6/core/include \
  -I"${TB_DIR}" \
  /home/cva6/core/include/config_pkg.sv \
  "${TB_DIR}/cva6_config_pkg.sv" \
  /home/cva6/core/include/riscv_pkg.sv \
  /home/cva6/core/include/ariane_pkg.sv \
  /home/cva6/core/include/build_config_pkg.sv \
  /home/cva6/core/include/std_cache_pkg.sv \
  /home/cva6/core/cache_subsystem/cache_ctrl.sv \
  "${TB_DIR}/${TB_TOP}.sv" \
  > "${BUILD_LOG}" 2>&1
rc=$?
if [[ ${rc} -eq 0 ]]; then
  "${OBJ_DIR}/V${TB_TOP}" > "${RUN_LOG}" 2>&1
  rc=$?
fi
set -e

if [[ ${rc} -ne 0 ]]; then
  if [[ -f "${BUILD_LOG}" ]]; then
    tail -n 40 "${BUILD_LOG}" || true
  fi
  if [[ -f "${RUN_LOG}" ]]; then
    tail -n 40 "${RUN_LOG}" || true
  fi
fi

echo "HWE_BENCH_RESULTS_START"
if [[ ${rc} -eq 0 ]]; then
  echo "TEST: cache_ctrl_axi_lane_align ... PASS"
else
  echo "TEST: cache_ctrl_axi_lane_align ... FAIL"
fi
echo "HWE_BENCH_RESULTS_END"

exit "${rc}"

#!/bin/bash
set -uo pipefail

cd /home/cva6 || exit 1

REQ_VER=""
if [ -f verif/regress/install-verilator.sh ]; then
  REQ_VER=$(sed -n 's/.*VERILATOR_HASH="\([^"]*\)".*/\1/p' verif/regress/install-verilator.sh | head -n1)
elif [ -f ci/install-verilator.sh ]; then
  REQ_VER=$(sed -n 's/.*VERILATOR_HASH="\([^"]*\)".*/\1/p' ci/install-verilator.sh | head -n1)
fi

VERILATOR_BASE=/tools/verilator
if [ -n "$REQ_VER" ] && [ -d "/tools/verilator-$REQ_VER" ]; then
  VERILATOR_BASE="/tools/verilator-$REQ_VER"
fi

VERILATOR_BIN_DIR="$VERILATOR_BASE/bin"
VERILATOR_ROOT_DIR="$VERILATOR_BASE/share/verilator"
VERILATOR_CMD="$VERILATOR_BIN_DIR/verilator"

if [ ! -x "$VERILATOR_CMD" ] || [ ! -x "$VERILATOR_BIN_DIR/verilator_bin" ] || [ ! -x "$VERILATOR_ROOT_DIR/bin/verilator_includer" ]; then
  echo "Required Verilator layout is unavailable under $VERILATOR_BASE" >&2
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: shared_tlb_false_hit_asid ... FAIL"
  echo "HWE_BENCH_RESULTS_END"
  exit 1
fi

# The installed wrapper already knows its absolute layout. Keeping the harness
# VERILATOR_* environment here makes it build an invalid nested path.
unset VERILATOR_INSTALL_DIR
unset VERILATOR_ROOT
unset VERILATOR_BIN

TB_DIR=/home/cva6/.tb_shared_tlb_false_hit
BUILD_LOG="$TB_DIR/build.log"
SIM_LOG="$TB_DIR/sim.log"

rm -rf "$TB_DIR"
mkdir -p "$TB_DIR"

cat > "$TB_DIR/tb.sv" <<'EOF'
`timescale 1ns/1ps

module sram #(
    parameter int unsigned DATA_WIDTH = 64,
    parameter int unsigned NUM_WORDS  = 1024,
    parameter int unsigned USER_WIDTH = 1
) (
    input  logic                          clk_i,
    input  logic                          rst_ni,
    input  logic                          req_i,
    input  logic                          we_i,
    input  logic [$clog2(NUM_WORDS)-1:0]  addr_i,
    input  logic [USER_WIDTH-1:0]         wuser_i,
    input  logic [DATA_WIDTH-1:0]         wdata_i,
    input  logic [DATA_WIDTH-1:0]         be_i,
    output logic [USER_WIDTH-1:0]         ruser_o,
    output logic [DATA_WIDTH-1:0]         rdata_o
);
  logic [DATA_WIDTH-1:0] ram [NUM_WORDS-1:0];
  logic [$clog2(NUM_WORDS)-1:0] raddr_q;

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      raddr_q <= '0;
    end else if (req_i) begin
      if (we_i) begin
        for (int unsigned i = 0; i < DATA_WIDTH; i++) begin
          if (be_i[i]) begin
            ram[addr_i][i] <= wdata_i[i];
          end
        end
      end else begin
        raddr_q <= addr_i;
      end
    end
  end

  assign ruser_o = '0;
  assign rdata_o = ram[raddr_q];
endmodule

module tb;
  localparam config_pkg::cva6_cfg_t CVA6Cfg = build_config_pkg::build_config(
      cva6_config_pkg::cva6_cfg
  );
  localparam int unsigned HYP_EXT = 0;
  localparam int unsigned VLEN = CVA6Cfg.VLEN;
  localparam int unsigned ASID_WIDTH = CVA6Cfg.ASID_WIDTH;
  localparam int unsigned VMID_WIDTH = CVA6Cfg.VMID_WIDTH;
  localparam int unsigned PPNW = CVA6Cfg.PPNW;
  localparam int unsigned PT_LEVELS = CVA6Cfg.PtLevels;
  localparam int unsigned VPN_LEN = CVA6Cfg.VpnLen;
  localparam int unsigned SV = CVA6Cfg.SV;

  typedef struct packed {
    logic [9:0] reserved;
    logic [PPNW-1:0] ppn;
    logic [1:0] rsw;
    logic d;
    logic a;
    logic g;
    logic u;
    logic x;
    logic w;
    logic r;
    logic v;
  } pte_cva6_t;

  typedef struct packed {
    logic valid;
    logic [PT_LEVELS-2:0][HYP_EXT:0] is_page;
    logic [VPN_LEN-1:0] vpn;
    logic [ASID_WIDTH-1:0] asid;
    logic [VMID_WIDTH-1:0] vmid;
    logic [HYP_EXT*2:0] v_st_enbl;
    pte_cva6_t content;
    pte_cva6_t g_content;
  } tlb_update_cva6_t;

  logic clk_i;
  logic rst_ni;
  logic flush_i;
  logic flush_vvma_i;
  logic flush_gvma_i;
  logic s_st_enbl_i;
  logic g_st_enbl_i;
  logic v_i;
  logic s_ld_st_enbl_i;
  logic g_ld_st_enbl_i;
  logic ld_st_v_i;
  logic [ASID_WIDTH-1:0] dtlb_asid_i;
  logic [ASID_WIDTH-1:0] itlb_asid_i;
  logic [VMID_WIDTH-1:0] lu_vmid_i;
  logic itlb_access_i;
  logic itlb_hit_i;
  logic [VLEN-1:0] itlb_vaddr_i;
  logic dtlb_access_i;
  logic dtlb_hit_i;
  logic [VLEN-1:0] dtlb_vaddr_i;
  logic shared_tlb_miss_i;
  tlb_update_cva6_t itlb_update_o;
  tlb_update_cva6_t dtlb_update_o;
  logic itlb_miss_o;
  logic dtlb_miss_o;
  logic shared_tlb_access_o;
  logic shared_tlb_hit_o;
  logic [VLEN-1:0] shared_tlb_vaddr_o;
  logic itlb_req_o;
  tlb_update_cva6_t shared_tlb_update_i;

  localparam logic [VLEN-1:0] TARGET_VADDR = 32'h0001_5000;
  localparam logic [VLEN-1:0] HELPER_VADDR = 32'h0041_5000;
  localparam logic [PPNW-1:0] TARGET_PPN = 22'h12A55;
  localparam logic [PPNW-1:0] HELPER_PPN = 22'h2B3CC;

  cva6_shared_tlb #(
      .CVA6Cfg(CVA6Cfg),
      .pte_cva6_t(pte_cva6_t),
      .tlb_update_cva6_t(tlb_update_cva6_t),
      .SHARED_TLB_WAYS(2),
      .HYP_EXT(HYP_EXT)
  ) dut (
      .clk_i(clk_i),
      .rst_ni(rst_ni),
      .flush_i(flush_i),
      .flush_vvma_i(flush_vvma_i),
      .flush_gvma_i(flush_gvma_i),
      .s_st_enbl_i(s_st_enbl_i),
      .g_st_enbl_i(g_st_enbl_i),
      .v_i(v_i),
      .s_ld_st_enbl_i(s_ld_st_enbl_i),
      .g_ld_st_enbl_i(g_ld_st_enbl_i),
      .ld_st_v_i(ld_st_v_i),
      .dtlb_asid_i(dtlb_asid_i),
      .itlb_asid_i(itlb_asid_i),
      .lu_vmid_i(lu_vmid_i),
      .itlb_access_i(itlb_access_i),
      .itlb_hit_i(itlb_hit_i),
      .itlb_vaddr_i(itlb_vaddr_i),
      .dtlb_access_i(dtlb_access_i),
      .dtlb_hit_i(dtlb_hit_i),
      .dtlb_vaddr_i(dtlb_vaddr_i),
      .shared_tlb_miss_i(shared_tlb_miss_i),
      .itlb_update_o(itlb_update_o),
      .dtlb_update_o(dtlb_update_o),
      .itlb_miss_o(itlb_miss_o),
      .dtlb_miss_o(dtlb_miss_o),
      .shared_tlb_access_o(shared_tlb_access_o),
      .shared_tlb_hit_o(shared_tlb_hit_o),
      .shared_tlb_vaddr_o(shared_tlb_vaddr_o),
      .itlb_req_o(itlb_req_o),
      .shared_tlb_update_i(shared_tlb_update_i)
  );

  always #1 clk_i = ~clk_i;

  function automatic pte_cva6_t make_pte(input logic [PPNW-1:0] ppn);
    pte_cva6_t pte;
    pte = '0;
    pte.ppn = ppn;
    pte.d = 1'b1;
    pte.a = 1'b1;
    pte.x = 1'b1;
    pte.w = 1'b1;
    pte.r = 1'b1;
    pte.v = 1'b1;
    return pte;
  endfunction

  task automatic drive_idle();
    flush_i = 1'b0;
    flush_vvma_i = 1'b0;
    flush_gvma_i = 1'b0;
    s_st_enbl_i = 1'b0;
    g_st_enbl_i = 1'b0;
    v_i = 1'b0;
    s_ld_st_enbl_i = 1'b0;
    g_ld_st_enbl_i = 1'b0;
    ld_st_v_i = 1'b0;
    dtlb_asid_i = '0;
    itlb_asid_i = '0;
    lu_vmid_i = '0;
    itlb_access_i = 1'b0;
    itlb_hit_i = 1'b0;
    itlb_vaddr_i = '0;
    dtlb_access_i = 1'b0;
    dtlb_hit_i = 1'b0;
    dtlb_vaddr_i = '0;
    shared_tlb_miss_i = 1'b0;
    shared_tlb_update_i = '0;
  endtask

  task automatic step();
    @(posedge clk_i);
    @(negedge clk_i);
  endtask

  task automatic insert_itlb_entry(
      input logic [VLEN-1:0] vaddr,
      input logic [ASID_WIDTH-1:0] asid,
      input logic [PPNW-1:0] ppn
  );
    drive_idle();
    s_st_enbl_i = 1'b1;
    itlb_access_i = 1'b1;
    itlb_hit_i = 1'b0;
    itlb_vaddr_i = vaddr;
    itlb_asid_i = asid;
    shared_tlb_miss_i = 1'b1;
    step();

    drive_idle();
    s_st_enbl_i = 1'b1;
    itlb_asid_i = asid;
    shared_tlb_update_i.valid = 1'b1;
    shared_tlb_update_i.is_page = '0;
    shared_tlb_update_i.vpn = vaddr[SV-1:12];
    shared_tlb_update_i.asid = asid;
    shared_tlb_update_i.vmid = '0;
    shared_tlb_update_i.v_st_enbl = '0;
    shared_tlb_update_i.content = make_pte(ppn);
    shared_tlb_update_i.g_content = '0;
    step();

    drive_idle();
    step();
  endtask

  task automatic expect_hit(
      input logic [VLEN-1:0] vaddr,
      input logic [ASID_WIDTH-1:0] asid,
      input logic [PPNW-1:0] expected_ppn
  );
    drive_idle();
    s_st_enbl_i = 1'b1;
    itlb_access_i = 1'b1;
    itlb_hit_i = 1'b0;
    itlb_vaddr_i = vaddr;
    itlb_asid_i = asid;
    shared_tlb_miss_i = 1'b1;
    step();

    if (!shared_tlb_hit_o || !itlb_update_o.valid || (itlb_update_o.content.ppn !== expected_ppn)) begin
      $display(
          "Expected hit for vaddr=%h asid=%0h, got hit=%0b valid=%0b ppn=%h",
          vaddr,
          asid,
          shared_tlb_hit_o,
          itlb_update_o.valid,
          itlb_update_o.content.ppn
      );
      $fatal(1, "Positive control lookup failed");
    end

    drive_idle();
    step();
  endtask

  task automatic expect_miss(
      input logic [VLEN-1:0] vaddr,
      input logic [ASID_WIDTH-1:0] asid
  );
    drive_idle();
    s_st_enbl_i = 1'b1;
    itlb_access_i = 1'b1;
    itlb_hit_i = 1'b0;
    itlb_vaddr_i = vaddr;
    itlb_asid_i = asid;
    shared_tlb_miss_i = 1'b1;
    step();

    if (shared_tlb_hit_o || itlb_update_o.valid) begin
      $display(
          "Unexpected shared TLB hit for vaddr=%h asid=%0h, returned ppn=%h",
          vaddr,
          asid,
          itlb_update_o.content.ppn
      );
      $fatal(1, "Shared TLB produced a false hit");
    end

    drive_idle();
    step();
  endtask

  initial begin
    clk_i = 1'b0;
    rst_ni = 1'b0;
    drive_idle();

    repeat (2) step();
    rst_ni = 1'b1;
    step();

    insert_itlb_entry(HELPER_VADDR, 1'b1, HELPER_PPN);
    insert_itlb_entry(TARGET_VADDR, 1'b0, TARGET_PPN);

    expect_hit(HELPER_VADDR, 1'b1, HELPER_PPN);
    expect_miss(TARGET_VADDR, 1'b1);

    $display("shared_tlb_false_hit_asid test completed");
    $finish;
  end
endmodule
EOF

set +e
"$VERILATOR_CMD" -sv --binary --timing -Wno-fatal -j "$(nproc)" \
  -Wno-TIMESCALEMOD -Wno-WIDTHTRUNC -Wno-WIDTHEXPAND \
  --Mdir "$TB_DIR/obj_dir" \
  --top-module tb \
  vendor/pulp-platform/common_cells/src/cf_math_pkg.sv \
  core/include/config_pkg.sv \
  core/include/build_config_pkg.sv \
  core/include/cv32a6_imac_sv32_config_pkg.sv \
  vendor/pulp-platform/common_cells/src/lzc.sv \
  vendor/pulp-platform/common_cells/src/lfsr_8bit.sv \
  vendor/pulp-platform/common_cells/src/lfsr_16bit.sv \
  vendor/pulp-platform/common_cells/src/lfsr.sv \
  core/cva6_mmu/cva6_shared_tlb.sv \
  "$TB_DIR/tb.sv" \
  >"$BUILD_LOG" 2>&1
build_rc=$?

run_rc=0
if [ "$build_rc" -eq 0 ]; then
  "$TB_DIR/obj_dir/Vtb" >"$SIM_LOG" 2>&1
  run_rc=$?
fi
set -e

rc=$build_rc
if [ "$rc" -eq 0 ]; then
  rc=$run_rc
fi

[ -f "$BUILD_LOG" ] && cat "$BUILD_LOG"
[ -f "$SIM_LOG" ] && cat "$SIM_LOG"

echo "HWE_BENCH_RESULTS_START"
if [ "$rc" -eq 0 ]; then
  echo "TEST: shared_tlb_false_hit_asid ... PASS"
else
  echo "TEST: shared_tlb_false_hit_asid ... FAIL"
fi
echo "HWE_BENCH_RESULTS_END"

exit "$rc"

