tb_script:
#!/bin/bash

set -uo pipefail

cd /home/cva6 || exit 1

if [ -f /etc/cva6_tools_path.sh ]; then
  # Reuse the preinstalled toolchain paths from the base image.
  source /etc/cva6_tools_path.sh
fi

VERILATOR_CMD="/tools/verilator/bin/verilator"

TB_NAME="misaligned_lsu_no_spurious_ptw"
TB_DIR="/home/cva6/.tb_${TB_NAME}"
BUILD_LOG="$TB_DIR/build.log"
SIM_LOG="$TB_DIR/sim.log"

rm -rf "$TB_DIR"
mkdir -p "$TB_DIR"

cat > "$TB_DIR/tb_misaligned_mmu.sv" <<'EOF'
`timescale 1ns/1ps

module tb_misaligned_mmu;
  import ariane_pkg::*;

  localparam config_pkg::cva6_cfg_t CVA6Cfg = build_config_pkg::build_config(cva6_config_pkg::cva6_cfg);

  typedef struct packed {
    logic [CVA6Cfg.XLEN-1:0] cause;
    logic [CVA6Cfg.XLEN-1:0] tval;
    logic [CVA6Cfg.GPLEN-1:0] tval2;
    logic [31:0] tinst;
    logic gva;
    logic valid;
  } exception_t;

  typedef struct packed {
    logic                    fetch_valid;
    logic [CVA6Cfg.PLEN-1:0] fetch_paddr;
    exception_t              fetch_exception;
  } icache_areq_t;

  typedef struct packed {
    logic                    fetch_req;
    logic [CVA6Cfg.VLEN-1:0] fetch_vaddr;
  } icache_arsp_t;

  typedef struct packed {
    logic [CVA6Cfg.DCACHE_INDEX_WIDTH-1:0] address_index;
    logic [CVA6Cfg.DCACHE_TAG_WIDTH-1:0]   address_tag;
    logic [CVA6Cfg.XLEN-1:0]               data_wdata;
    logic [CVA6Cfg.DCACHE_USER_WIDTH-1:0]  data_wuser;
    logic                                  data_req;
    logic                                  data_we;
    logic [(CVA6Cfg.XLEN/8)-1:0]           data_be;
    logic [1:0]                            data_size;
    logic [CVA6Cfg.DcacheIdWidth-1:0]      data_id;
    logic                                  kill_req;
    logic                                  tag_valid;
  } dcache_req_i_t;

  typedef struct packed {
    logic                                 data_gnt;
    logic                                 data_rvalid;
    logic [CVA6Cfg.DcacheIdWidth-1:0]     data_rid;
    logic [CVA6Cfg.XLEN-1:0]              data_rdata;
    logic [CVA6Cfg.DCACHE_USER_WIDTH-1:0] data_ruser;
  } dcache_req_o_t;

  logic clk_i = 1'b0;
  logic rst_ni = 1'b0;

  logic flush_i = 1'b0;
  logic enable_translation_i = 1'b0;
  logic enable_g_translation_i = 1'b0;
  logic en_ld_st_translation_i = 1'b1;
  logic en_ld_st_g_translation_i = 1'b0;

  icache_arsp_t icache_areq_i = '0;
  icache_areq_t icache_areq_o;

  exception_t misaligned_ex_i = '0;
  logic lsu_req_i = 1'b0;
  logic [CVA6Cfg.VLEN-1:0] lsu_vaddr_i = '0;
  logic [31:0] lsu_tinst_i = '0;
  logic lsu_is_store_i = 1'b0;
  logic csr_hs_ld_st_inst_o;
  logic lsu_dtlb_hit_o;
  logic [CVA6Cfg.PPNW-1:0] lsu_dtlb_ppn_o;
  logic lsu_valid_o;
  logic [CVA6Cfg.PLEN-1:0] lsu_paddr_o;
  exception_t lsu_exception_o;

  riscv::priv_lvl_t priv_lvl_i = riscv::PRIV_LVL_S;
  logic v_i = 1'b0;
  riscv::priv_lvl_t ld_st_priv_lvl_i = riscv::PRIV_LVL_S;
  logic ld_st_v_i = 1'b0;
  logic sum_i = 1'b0;
  logic vs_sum_i = 1'b0;
  logic mxr_i = 1'b0;
  logic vmxr_i = 1'b0;
  logic hlvx_inst_i = 1'b0;
  logic hs_ld_st_inst_i = 1'b0;
  logic [CVA6Cfg.PPNW-1:0] satp_ppn_i = CVA6Cfg.PPNW'(22'h1);
  logic [CVA6Cfg.PPNW-1:0] vsatp_ppn_i = '0;
  logic [CVA6Cfg.PPNW-1:0] hgatp_ppn_i = '0;
  logic [CVA6Cfg.ASID_WIDTH-1:0] asid_i = '0;
  logic [CVA6Cfg.ASID_WIDTH-1:0] vs_asid_i = '0;
  logic [CVA6Cfg.ASID_WIDTH-1:0] asid_to_be_flushed_i = '0;
  logic [CVA6Cfg.VMID_WIDTH-1:0] vmid_i = '0;
  logic [CVA6Cfg.VMID_WIDTH-1:0] vmid_to_be_flushed_i = '0;
  logic [CVA6Cfg.VLEN-1:0] vaddr_to_be_flushed_i = '0;
  logic [CVA6Cfg.GPLEN-1:0] gpaddr_to_be_flushed_i = '0;
  logic flush_tlb_i = 1'b0;
  logic flush_tlb_vvma_i = 1'b0;
  logic flush_tlb_gvma_i = 1'b0;

  logic itlb_miss_o;
  logic dtlb_miss_o;
  dcache_req_o_t req_port_i = '0;
  dcache_req_i_t req_port_o;

  riscv::pmpcfg_t [avoid_neg(CVA6Cfg.NrPMPEntries-1):0] pmpcfg_i = '0;
  logic [avoid_neg(CVA6Cfg.NrPMPEntries-1):0][CVA6Cfg.PLEN-3:0] pmpaddr_i = '0;

  bit saw_spurious_ptw = 1'b0;
  bit saw_misaligned_exception = 1'b0;

  always #5 clk_i = ~clk_i;

  cva6_mmu #(
      .CVA6Cfg(CVA6Cfg),
      .icache_areq_t(icache_areq_t),
      .icache_arsp_t(icache_arsp_t),
      .dcache_req_i_t(dcache_req_i_t),
      .dcache_req_o_t(dcache_req_o_t),
      .exception_t(exception_t),
      .HYP_EXT(0)
  ) dut (
      .clk_i(clk_i),
      .rst_ni(rst_ni),
      .flush_i(flush_i),
      .enable_translation_i(enable_translation_i),
      .enable_g_translation_i(enable_g_translation_i),
      .en_ld_st_translation_i(en_ld_st_translation_i),
      .en_ld_st_g_translation_i(en_ld_st_g_translation_i),
      .icache_areq_i(icache_areq_i),
      .icache_areq_o(icache_areq_o),
      .misaligned_ex_i(misaligned_ex_i),
      .lsu_req_i(lsu_req_i),
      .lsu_vaddr_i(lsu_vaddr_i),
      .lsu_tinst_i(lsu_tinst_i),
      .lsu_is_store_i(lsu_is_store_i),
      .csr_hs_ld_st_inst_o(csr_hs_ld_st_inst_o),
      .lsu_dtlb_hit_o(lsu_dtlb_hit_o),
      .lsu_dtlb_ppn_o(lsu_dtlb_ppn_o),
      .lsu_valid_o(lsu_valid_o),
      .lsu_paddr_o(lsu_paddr_o),
      .lsu_exception_o(lsu_exception_o),
      .priv_lvl_i(priv_lvl_i),
      .v_i(v_i),
      .ld_st_priv_lvl_i(ld_st_priv_lvl_i),
      .ld_st_v_i(ld_st_v_i),
      .sum_i(sum_i),
      .vs_sum_i(vs_sum_i),
      .mxr_i(mxr_i),
      .vmxr_i(vmxr_i),
      .hlvx_inst_i(hlvx_inst_i),
      .hs_ld_st_inst_i(hs_ld_st_inst_i),
      .satp_ppn_i(satp_ppn_i),
      .vsatp_ppn_i(vsatp_ppn_i),
      .hgatp_ppn_i(hgatp_ppn_i),
      .asid_i(asid_i),
      .vs_asid_i(vs_asid_i),
      .asid_to_be_flushed_i(asid_to_be_flushed_i),
      .vmid_i(vmid_i),
      .vmid_to_be_flushed_i(vmid_to_be_flushed_i),
      .vaddr_to_be_flushed_i(vaddr_to_be_flushed_i),
      .gpaddr_to_be_flushed_i(gpaddr_to_be_flushed_i),
      .flush_tlb_i(flush_tlb_i),
      .flush_tlb_vvma_i(flush_tlb_vvma_i),
      .flush_tlb_gvma_i(flush_tlb_gvma_i),
      .itlb_miss_o(itlb_miss_o),
      .dtlb_miss_o(dtlb_miss_o),
      .req_port_i(req_port_i),
      .req_port_o(req_port_o),
      .pmpcfg_i(pmpcfg_i),
      .pmpaddr_i(pmpaddr_i)
  );

  always @(posedge clk_i) begin
    if (rst_ni && req_port_o.data_req) begin
      saw_spurious_ptw <= 1'b1;
    end
    if (rst_ni && lsu_valid_o && lsu_exception_o.valid) begin
      saw_misaligned_exception <= 1'b1;
    end
  end

  initial begin
    enable_translation_i = 1'b1;
    lsu_vaddr_i = 32'h0040_1003;

    repeat (2) @(posedge clk_i);
    rst_ni = 1'b1;

    @(posedge clk_i);
    misaligned_ex_i.valid <= 1'b1;
    misaligned_ex_i.cause <= 32'd4;
    misaligned_ex_i.tval <= 32'h0040_1003;
    lsu_req_i <= 1'b1;

    @(posedge clk_i);
    misaligned_ex_i <= '0;
    lsu_req_i <= 1'b0;

    repeat (6) @(posedge clk_i);

    if (!saw_misaligned_exception) begin
      $fatal(1, "misaligned exception was not reported by the MMU");
    end

    if (saw_spurious_ptw) begin
      $fatal(1, "spurious page-table request observed for a misaligned LSU access");
    end

    $display("tb_misaligned_mmu: PASS");
    $finish;
  end
endmodule
EOF

cat > "$TB_DIR/files.f" <<'EOF'
