tb_script:
#!/bin/bash
set -euo pipefail

cd /home/cva6

if [[ -f /etc/cva6_tools_path.sh ]]; then
  # shellcheck disable=SC1091
  source /etc/cva6_tools_path.sh
fi

export PATH="/tools/verilator/bin:${PATH}"
export CVA6_REPO_DIR=/home/cva6
export TARGET_CFG=hwconfig
export HPDCACHE_DIR=/home/cva6/core/cache_subsystem/hpdcache

TB_NAME=cvxif_no_rvc_id_stage
TB_DIR=/home/cva6/.tb_id_stage_cvxif_no_rvc
TB_SV="$TB_DIR/tb_id_stage_cvxif_no_rvc.sv"
RUN_LOG="$TB_DIR/run.log"

rm -rf "$TB_DIR"
mkdir -p "$TB_DIR"

python3 - <<'PY'
from pathlib import Path

src = Path("/home/cva6/core/include/cv32a60x_config_pkg.sv").read_text()
src = src.replace("RVC: bit'(1)", "RVC: bit'(0)")
src = src.replace("RVZCB: bit'(1)", "RVZCB: bit'(0)")
Path("/home/cva6/core/include/hwconfig_config_pkg.sv").write_text(src)
PY

cat > "$TB_SV" <<'EOF'
module tb_id_stage_cvxif_no_rvc;
  import ariane_pkg::*;

  localparam config_pkg::cva6_cfg_t CVA6Cfg = build_config_pkg::build_config(cva6_config_pkg::cva6_cfg);

  localparam type branchpredict_sbe_t = struct packed {
    cf_t                     cf;
    logic [CVA6Cfg.VLEN-1:0] predict_address;
  };

  localparam type exception_t = struct packed {
    logic [CVA6Cfg.XLEN-1:0]  cause;
    logic [CVA6Cfg.XLEN-1:0]  tval;
    logic [CVA6Cfg.GPLEN-1:0] tval2;
    logic [31:0]              tinst;
    logic                     gva;
    logic                     valid;
  };

  localparam type fetch_entry_t = struct packed {
    logic [CVA6Cfg.VLEN-1:0] address;
    logic [31:0]             instruction;
    branchpredict_sbe_t      branch_predict;
    exception_t              ex;
  };

  localparam type jvt_t = struct packed {
    logic [CVA6Cfg.XLEN-7:0] base;
    logic [5:0]              mode;
  };

  localparam type scoreboard_entry_t = struct packed {
    logic [CVA6Cfg.VLEN-1:0]          pc;
    logic [CVA6Cfg.TRANS_ID_BITS-1:0] trans_id;
    fu_t                              fu;
    fu_op                             op;
    logic [REG_ADDR_SIZE-1:0]         rs1;
    logic [REG_ADDR_SIZE-1:0]         rs2;
    logic [REG_ADDR_SIZE-1:0]         rd;
    logic [CVA6Cfg.XLEN-1:0]          result;
    logic                             valid;
    logic                             use_imm;
    logic                             use_zimm;
    logic                             use_pc;
    exception_t                       ex;
    branchpredict_sbe_t               bp;
    logic                             is_compressed;
    logic                             is_macro_instr;
    logic                             is_last_macro_instr;
    logic                             is_double_rd_macro_instr;
    logic                             vfp;
    logic                             is_zcmt;
  };

  localparam type irq_ctrl_t = struct packed {
    logic [CVA6Cfg.XLEN-1:0] mie;
    logic [CVA6Cfg.XLEN-1:0] mip;
    logic [CVA6Cfg.XLEN-1:0] mideleg;
    logic [CVA6Cfg.XLEN-1:0] hideleg;
    logic                    sie;
    logic                    global_enable;
  };

  localparam type interrupts_t = struct packed {
    logic [CVA6Cfg.XLEN-1:0] S_SW;
    logic [CVA6Cfg.XLEN-1:0] VS_SW;
    logic [CVA6Cfg.XLEN-1:0] M_SW;
    logic [CVA6Cfg.XLEN-1:0] S_TIMER;
    logic [CVA6Cfg.XLEN-1:0] VS_TIMER;
    logic [CVA6Cfg.XLEN-1:0] M_TIMER;
    logic [CVA6Cfg.XLEN-1:0] S_EXT;
    logic [CVA6Cfg.XLEN-1:0] VS_EXT;
    logic [CVA6Cfg.XLEN-1:0] M_EXT;
    logic [CVA6Cfg.XLEN-1:0] HS_EXT;
  };

  localparam interrupts_t INTERRUPTS = '{
    S_SW:     (CVA6Cfg.XLEN'(1) << (CVA6Cfg.XLEN - 1)) | CVA6Cfg.XLEN'(riscv::IRQ_S_SOFT),
    VS_SW:    (CVA6Cfg.XLEN'(1) << (CVA6Cfg.XLEN - 1)) | CVA6Cfg.XLEN'(riscv::IRQ_VS_SOFT),
    M_SW:     (CVA6Cfg.XLEN'(1) << (CVA6Cfg.XLEN - 1)) | CVA6Cfg.XLEN'(riscv::IRQ_M_SOFT),
    S_TIMER:  (CVA6Cfg.XLEN'(1) << (CVA6Cfg.XLEN - 1)) | CVA6Cfg.XLEN'(riscv::IRQ_S_TIMER),
    VS_TIMER: (CVA6Cfg.XLEN'(1) << (CVA6Cfg.XLEN - 1)) | CVA6Cfg.XLEN'(riscv::IRQ_VS_TIMER),
    M_TIMER:  (CVA6Cfg.XLEN'(1) << (CVA6Cfg.XLEN - 1)) | CVA6Cfg.XLEN'(riscv::IRQ_M_TIMER),
    S_EXT:    (CVA6Cfg.XLEN'(1) << (CVA6Cfg.XLEN - 1)) | CVA6Cfg.XLEN'(riscv::IRQ_S_EXT),
    VS_EXT:   (CVA6Cfg.XLEN'(1) << (CVA6Cfg.XLEN - 1)) | CVA6Cfg.XLEN'(riscv::IRQ_VS_EXT),
    M_EXT:    (CVA6Cfg.XLEN'(1) << (CVA6Cfg.XLEN - 1)) | CVA6Cfg.XLEN'(riscv::IRQ_M_EXT),
    HS_EXT:   (CVA6Cfg.XLEN'(1) << (CVA6Cfg.XLEN - 1)) | CVA6Cfg.XLEN'(riscv::IRQ_HS_EXT)
  };

  localparam logic [31:0] TEST_INSTR = 32'h00100093;

  logic clk_i;
  logic rst_ni;
  logic flush_i;
  logic debug_req_i;
  fetch_entry_t [CVA6Cfg.NrIssuePorts-1:0] fetch_entry_i;
  logic [CVA6Cfg.NrIssuePorts-1:0] fetch_entry_valid_i;
  logic [CVA6Cfg.NrIssuePorts-1:0] fetch_entry_ready_o;
  scoreboard_entry_t [CVA6Cfg.NrIssuePorts-1:0] issue_entry_o;
  scoreboard_entry_t [CVA6Cfg.NrIssuePorts-1:0] issue_entry_o_prev;
  logic [CVA6Cfg.NrIssuePorts-1:0][31:0] orig_instr_o;
  logic [CVA6Cfg.NrIssuePorts-1:0] issue_entry_valid_o;
  logic [CVA6Cfg.NrIssuePorts-1:0] is_ctrl_flow_o;
  logic [CVA6Cfg.NrIssuePorts-1:0] issue_instr_ack_i;
  logic [CVA6Cfg.NrIssuePorts-1:0] rvfi_is_compressed_o;
  riscv::priv_lvl_t priv_lvl_i;
  logic v_i;
  riscv::xs_t fs_i;
  riscv::xs_t vfs_i;
  logic [2:0] frm_i;
  riscv::xs_t vs_i;
  logic [1:0] irq_i;
  irq_ctrl_t irq_ctrl_i;
  logic debug_mode_i;
  logic tvm_i;
  logic tw_i;
  logic vtw_i;
  logic tsr_i;
  logic hu_i;
  riscv::cbie_t mcbie_i;
  riscv::cbie_t scbie_i;
  riscv::cbie_t hcbie_i;
  logic mcbcfe_i;
  logic scbcfe_i;
  logic hcbcfe_i;
  logic [CVA6Cfg.XLEN-1:0] hart_id_i;
  logic compressed_ready_i;
  jvt_t jvt_i;
  logic compressed_resp_i;
  logic compressed_valid_o;
  logic compressed_req_o;
  logic debug_from_trigger_i;
  logic dcache_req_ports_i;
  logic dcache_req_ports_o;

  id_stage #(
    .CVA6Cfg(CVA6Cfg),
    .branchpredict_sbe_t(branchpredict_sbe_t),
    .dcache_req_i_t(logic),
    .dcache_req_o_t(logic),
    .exception_t(exception_t),
    .fetch_entry_t(fetch_entry_t),
    .jvt_t(jvt_t),
    .irq_ctrl_t(irq_ctrl_t),
    .scoreboard_entry_t(scoreboard_entry_t),
    .interrupts_t(interrupts_t),
    .INTERRUPTS(INTERRUPTS),
    .x_compressed_req_t(logic),
    .x_compressed_resp_t(logic)
  ) dut (
    .clk_i,
    .rst_ni,
    .flush_i,
    .debug_req_i,
    .fetch_entry_i,
    .fetch_entry_valid_i,
    .fetch_entry_ready_o,
    .issue_entry_o,
    .issue_entry_o_prev,
    .orig_instr_o,
    .issue_entry_valid_o,
    .is_ctrl_flow_o,
    .issue_instr_ack_i,
    .rvfi_is_compressed_o,
    .priv_lvl_i,
    .v_i,
    .fs_i,
    .vfs_i,
    .frm_i,
    .vs_i,
    .irq_i,
    .irq_ctrl_i,
    .debug_mode_i,
    .tvm_i,
    .tw_i,
    .vtw_i,
    .tsr_i,
    .hu_i,
    .mcbie_i,
    .scbie_i,
    .hcbie_i,
    .mcbcfe_i,
    .scbcfe_i,
    .hcbcfe_i,
    .hart_id_i,
    .compressed_ready_i,
    .jvt_i,
    .compressed_resp_i,
    .compressed_valid_o,
    .compressed_req_o,
    .debug_from_trigger_i,
    .dcache_req_ports_i,
    .dcache_req_ports_o
  );

  always #5 clk_i = ~clk_i;

  initial begin
    clk_i = 1'b0;
    rst_ni = 1'b0;
    flush_i = 1'b0;
    debug_req_i = 1'b0;
    fetch_entry_i = '0;
    fetch_entry_valid_i = '0;
    issue_instr_ack_i = '0;
    priv_lvl_i = riscv::priv_lvl_t'('0);
    v_i = 1'b0;
    fs_i = riscv::xs_t'('0);
    vfs_i = riscv::xs_t'('0);
    frm_i = '0;
    vs_i = riscv::xs_t'('0);
    irq_i = '0;
    irq_ctrl_i = '0;
    debug_mode_i = 1'b0;
    tvm_i = 1'b0;
    tw_i = 1'b0;
    vtw_i = 1'b0;
    tsr_i = 1'b0;
    hu_i = 1'b0;
    mcbie_i = riscv::cbie_t'('0);
    scbie_i = riscv::cbie_t'('0);
    hcbie_i = riscv::cbie_t'('0);
    mcbcfe_i = 1'b0;
    scbcfe_i = 1'b0;
    hcbcfe_i = 1'b0;
    hart_id_i = '0;
    compressed_ready_i = 1'b0;
    jvt_i = '0;
    compressed_resp_i = 1'b0;
    debug_from_trigger_i = 1'b0;
    dcache_req_ports_i = 1'b0;

    repeat (2) @(posedge clk_i);
    rst_ni = 1'b1;

    @(negedge clk_i);
    fetch_entry_i[0].address = 'h8000_0000;
    fetch_entry_i[0].instruction = TEST_INSTR;
    fetch_entry_valid_i[0] = 1'b1;

    @(negedge clk_i);
    fetch_entry_valid_i[0] = 1'b0;
    fetch_entry_i = '0;

    repeat (2) @(posedge clk_i);

    $display("DBG valid=%b orig=0x%08h rvfi_comp=%b", issue_entry_valid_o[0], orig_instr_o[0], rvfi_is_compressed_o[0]);
    if (issue_entry_valid_o[0] !== 1'b1) $fatal(1, "issue_entry_valid_o[0]=%b", issue_entry_valid_o[0]);
    if (orig_instr_o[0] !== TEST_INSTR) $fatal(1, "orig_instr_o[0]=0x%08h expected 0x%08h", orig_instr_o[0], TEST_INSTR);
    if (rvfi_is_compressed_o[0] !== 1'b0) $fatal(1, "rvfi_is_compressed_o[0]=%b", rvfi_is_compressed_o[0]);

    $display("TB_PASS");
    $finish;
  end

  initial begin
    repeat (20) @(posedge clk_i);
    $fatal(1, "timeout waiting for decode result");
  end
endmodule
EOF

: > "$RUN_LOG"

set +e
timeout 600 bash <<'EOF' 2>&1 | tee -a "$RUN_LOG"
set -euo pipefail
cd /home/cva6
export PATH="/tools/verilator/bin:${PATH}"
export CVA6_REPO_DIR=/home/cva6
export TARGET_CFG=hwconfig
export HPDCACHE_DIR=/home/cva6/core/cache_subsystem/hpdcache
TB_DIR=/home/cva6/.tb_id_stage_cvxif_no_rvc
verilator -sv --timing --binary --build \
  --top-module tb_id_stage_cvxif_no_rvc \
  -Wno-fatal \
  -Wno-UNUSEDSIGNAL \
  -Wno-UNDRIVEN \
  -Wno-WIDTH \
  -Wno-CASEINCOMPLETE \
  -Wno-BLKSEQ \
  -Mdir "$TB_DIR/obj_dir" \
  -f core/Flist.cva6 \
  "$TB_DIR/tb_id_stage_cvxif_no_rvc.sv"
"$TB_DIR/obj_dir/Vtb_id_stage_cvxif_no_rvc"
EOF
rc=${PIPESTATUS[0]}
set -e

echo "HWE_BENCH_RESULTS_START"
if [[ "$rc" -eq 0 ]]; then
  echo "TEST: $TB_NAME ... PASS"
else
  echo "TEST: $TB_NAME ... FAIL"
fi
echo "HWE_BENCH_RESULTS_END"

exit "$rc"
